#ifndef MODE
#define MODE 0
#endif
// The two quantised banks share every line below but the unpack: the LDS
// slab, the fp16 tail and the barriers are the same, so they are one arm with
// two spellings of "what a word holds".
#if defined(Q8B) || defined(Q4B)
#define QBANK 1
#endif
#ifndef WM
#define WM 4        // accumulator tiles, M direction
#endif
#ifndef WN
#define WN 4        // accumulator tiles, N direction; MODE 1 needs a multiple of 4
#endif
#ifndef BK_TILES
#define BK_TILES 2  // K-slab depth, in 16-wide cooperative-matrix steps
#endif
// The stream count is compiled in rather than read from pc.hc: MODE 1's
// collapse is a reduction over it *and* the weight permutation that puts the
// streams of one feature in one workgroup is cut on it, so a mismatch would
// be a wrong answer and not a slow one. The host checks the checkpoint says 4.
#ifndef HC_STREAMS
#define HC_STREAMS 4
#endif

#define TILE 16
#define BM (WM * TILE)
#define BN (WN * TILE)
#define BK (BK_TILES * TILE)
#define WAVE 64

layout(local_size_x = WAVE) in;

#ifdef QBANK
// §2.2's pad, and L5b's reason for its size: a slab row of BK + 8 halves
// keeps every row sixteen-byte aligned, which is what the cooperative-matrix
// load off LDS needs to take its wide path, and eight of the 32 banks is as
// good as a four-dword-aligned stride gets.
#define LDS_PAD 8
#define LDS_ROW (BK + LDS_PAD)
shared float16_t sQB[BN * LDS_ROW];
#endif

#ifdef Q4B
#include "llm_q4k.glsl"
// A k-slab is exactly one 32-element group, which is what lets the record be
// decoded once a slab into BN floats rather than once per unpacked word. It
// is a compile-time fact of every build in shaders.go and the arithmetic
// below assumes it rather than testing it.
#if BK != 32
#error "the q4_k arm wants BK_TILES = 2, so that a k-slab is one scale group"
#endif
shared float sQS[BN];   // d * sc for this slab's group, per column
shared float sQM[BN];   // dmin * m, the same
#endif

#define FRAG_A_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseA>
#define FRAG_B_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseB>
#define ACC_T coopmat<float, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseAccumulator>
#define ACC16_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseAccumulator>

#if MODE == 1
#define A_BUF_OFF pc.loOff
#define A_LDA pc.ldaLo
// The gate tiles go through LDS on the way to the collapse. Storing the
// accumulator and reading it back with ordinary indexing is what lets the
// collapse pair a gate element with its xn element without depending on how
// the implementation maps matrix elements to lanes -- which the cooperative
// matrix extension does not define.
//
// It holds **one m-tile**, not the whole row block: 4 KB and two barriers a
// tile, rather than BM x BN and one (L8b — see the epilogue). Beside the Q8
// arm's 5 KB unpack slab that is 9 KB at every rung of the ladder, where a
// [BM][BN] scratch would have been 21 at the widest.
//
// **This mode has no tail** — `hc_up.weight` is Q8_0 for all 10240 of its
// rows, and `pc.gateOff` here is not a weight at all but the validation arena
// the collapse optionally writes the wide gate into — so the tail branch is
// compiled out rather than guarded, which is what keeps the k-loop to one
// `coopMatLoad` of B (L8a-3).
shared float gateLDS[TILE * BN];
#else
// MODE 0 and MODE 2 both read the fp16 A operand at xnOff: the hyper-
// connection block's normalised residual, and the PLE block's gathered
// embedding.
#define A_BUF_OFF pc.xnOff
#define A_LDA pc.lda
#define Q8_TAIL 1
#if MODE == 0
// The column block holding the first non-Q8 row, not the row itself: see the
// note at the branch.
#define Q8_SPLIT ((pc.lowRank / BN) * BN)
#else
#define Q8_SPLIT pc.lowRank
#endif
#endif

float sigmoidf(float x) { return 1.0 / (1.0 + exp(-x)); }

void main() {
    uint wn0 = gl_WorkGroupID.x * BN;
    uint wm0 = gl_WorkGroupID.y * BM;

    ACC_T acc[WM][WN];
    [[unroll]] for (uint i = 0u; i < WM; i++) {
        [[unroll]] for (uint j = 0u; j < WN; j++) {
            acc[i][j] = ACC_T(0.0);
        }
    }

    uint ktiles = pc.gemmK / TILE;
#ifdef Q4B
    // The nibble tiles are at pc.bOff and the record plane follows them, so
    // its base is derivable and needs no push field of its own — the same
    // arrangement, and the same reason, as the Q8 arm below.
    uint qw0 = pc.bOff >> 2;                                   // the tiles, in words
    uint rec0 = (pc.bOff + ((pc.gemmN * pc.gemmK) >> 1)) >> 2; // the records, in words
    uint nsb = pc.gemmK >> 8;                                  // super-blocks a row
    uint lane = gl_LocalInvocationID.x;
    uint nt0 = wn0 / TILE;
    // This lane's column of the slab, and the record it holds for it. Lanes
    // at or past BN have no column; BN is 48 or 64 against a 64-wide wave.
    uvec4 myRec = uvec4(0u);
    uint myNT = nt0 + (lane >> 4), myRow = lane & 15u;
#endif
#ifdef Q8B
    // The tiles are bytes at pc.bOff and the scale plane is the halves that
    // follow them, so its base is derivable and needs no field of its own —
    // which matters, because 64 uints is this device's whole push range and
    // the block has been full since L5b. A matrix is staged as exactly
    // gemmN x gemmK bytes.
    uint qw0 = pc.bOff >> 2;                       // the tiles, in words
    uint sc0 = (pc.bOff + pc.gemmN * pc.gemmK) >> 1;  // the plane, in halves
    uint kgroups = pc.gemmK >> 5;
    uint lane = gl_LocalInvocationID.x;
    uint nt0 = wn0 / TILE;
#endif
#ifdef QBANK
#ifdef Q8_TAIL
    // **Not every row of a fused matrix is Q8_0 in the checkpoint**, and the
    // ones that are not stay halves rather than being re-quantised: the
    // gated DeltaNet's F32 alpha and beta, the attention layer's BF16 indexer
    // projections, the hyper-connection block's F32 inject. They are the
    // *last* rows of their matrix in every case, so the split is one number
    // and the tail is a fp16 fragment-tiled matrix of its own at
    // `pc.gateOff`, numbered from the split. A whole column block falls on
    // one side or the other, so the branch below is per workgroup and not per
    // tile.
    //
    // **Where the split falls is the one thing MODE 0 does differently**, and
    // it is L8b's whole difficulty. In MODE 2 the tail begins at
    // `pc.lowRank`, which is a whole BN block by construction because the
    // host chose the fused row order. In MODE 0 it cannot be: `inject` is
    // four F32 rows at lowRank = 320 of a fused N of 336, and BN is 48
    // because 336 is 21 tiles and 21 is 3 x 7. So the split is the *column
    // block that contains* the first non-Q8 row — `pc.lowRank` rounded down
    // to BN, 288 here — and the 32 low-rank rows between it and inject are
    // staged in both planes, read out of the fp16 one, and cost 0.33 MB a
    // mixer of the 3.2 the block saves.
    uint qSplit = Q8_SPLIT;
    bool tail = pc.gateOff != NO_W && wn0 >= qSplit;
    uint tailNT = nt0 - qSplit / TILE;
#endif
#endif
    // The reduction. On the Q8 arm it is written twice rather than branched
    // inside: the tail's B comes straight out of the fp16 bank as it always
    // did, the rest through LDS, and a compare in the k-loop cost 1.27x on
    // the DeltaNet's output projection — a matrix with no tail at all —
    // because the two `coopMatLoad`s in one loop body are register pressure
    // the ladder is already bound by (L2f-5, L3b-4).
#if defined(QBANK) && defined(Q8_TAIL)
    if (tail) {
        for (uint k0 = 0u; k0 < pc.gemmK; k0 += BK) {
            [[unroll]] for (uint kt = 0u; kt < BK_TILES; kt++) {
                FRAG_A_T fragA[WM];
                FRAG_B_T fragB[WN];
                [[unroll]] for (uint i = 0u; i < WM; i++) {
                    coopMatLoad(fragA[i], hact, A_BUF_OFF + (wm0 + i * TILE) * A_LDA + k0 + kt * TILE,
                        A_LDA, gl_CooperativeMatrixLayoutRowMajor);
                }
                [[unroll]] for (uint j = 0u; j < WN; j++) {
                    coopMatLoad(fragB[j], w16, pc.gateOff +
                        ((tailNT + j) * ktiles + (k0 + kt * TILE) / TILE) * (TILE * TILE),
                        TILE, gl_CooperativeMatrixLayoutColumnMajor);
                }
                [[unroll]] for (uint i = 0u; i < WM; i++) {
                    [[unroll]] for (uint j = 0u; j < WN; j++) {
                        acc[i][j] = coopMatMulAdd(fragA[i], fragB[j], acc[i][j]);
                    }
                }
            }
        }
    } else
#endif
    for (uint k0 = 0u; k0 < pc.gemmK; k0 += BK) {
#ifdef Q4B
        // The group parameters first, one lane a column. A record covers 256
        // k and this slab is 32, so the load is refreshed only where the loop
        // crosses a super-block and the rest is the six-bit unpack.
        if (lane < BN) {
            if ((k0 & 255u) == 0u) {
                uint idx = rec0 + ((myNT * nsb + (k0 >> 8)) * TILE + myRow) * 4u;
                myRec = uvec4(w8[idx], w8[idx + 1u], w8[idx + 2u], w8[idx + 3u]);
            }
            uint sc, mn;
            q4kScaleMin((k0 >> 5) & 7u, uvec3(myRec.y, myRec.z, myRec.w), sc, mn);
            vec2 dd = unpackHalf2x16(myRec.x);
            sQS[lane] = dd.x * float(sc);
            sQM[lane] = dd.y * float(mn);
        }
        barrier();
        // Unpack this workgroup's BN x BK slab. A tile is 128 contiguous
        // bytes and the tiles of one n-tile are contiguous across kt, so the
        // WN runs below are each BK_TILES * 32 words long; within a tile a
        // word is **eight** consecutive k of one output column, two to a
        // byte, low nibble first.
        uint kt0q = k0 / TILE;
        [[unroll]] for (uint j = 0u; j < WN; j++) {
            uint wbase = qw0 + ((nt0 + j) * ktiles + kt0q) * 32u;
            for (uint u = lane; u < BK_TILES * 32u; u += WAVE) {
                uint kt = u >> 5;
                uint wi = u & 31u;
                uint n = wi >> 1;              // 0..15, the output column
                uint kk = (wi & 1u) * 8u;      // eight consecutive k
                uint word = w8[wbase + u];
                float ds = sQS[j * TILE + n], dm = sQM[j * TILE + n];
                uint dst = (j * TILE + n) * LDS_ROW + kt * TILE + kk;
                [[unroll]] for (uint t = 0u; t < 4u; t++) {
                    uint by = bitfieldExtract(word, int(t * 8u), 8);
                    sQB[dst + t * 2u] = float16_t(ds * float(by & 0xFu) - dm);
                    sQB[dst + t * 2u + 1u] = float16_t(ds * float(by >> 4) - dm);
                }
            }
        }
        barrier();
#endif
#ifdef Q8B
        // Unpack this workgroup's BN x BK slab. A tile is 256 contiguous
        // bytes and the tiles of one n-tile are contiguous across kt, so the
        // WN runs below are each BK_TILES * 64 words long; within a tile a
        // word is four consecutive k of one output column, which is why one
        // scale serves it — a 32-element group is two whole k-tiles.
        uint kt0 = k0 / TILE;
        [[unroll]] for (uint j = 0u; j < WN; j++) {
            uint wbase = qw0 + ((nt0 + j) * ktiles + kt0) * 64u;
            uint sbase = sc0 + (nt0 + j) * kgroups * TILE;
            for (uint u = lane; u < BK_TILES * 64u; u += WAVE) {
                uint kt = u >> 6;
                uint b = (u & 63u) << 2;           // byte within the tile
                uint n = b >> 4;                   // 0..15, the output column
                uint kk = b & 15u;                 // 0..15, four consecutive k
                uint word = w8[wbase + u];
                float d = float(w16[sbase + ((kt0 + kt) >> 1) * TILE + n]);
                uint dst = (j * TILE + n) * LDS_ROW + kt * TILE + kk;
                [[unroll]] for (uint t = 0u; t < 4u; t++) {
                    sQB[dst + t] = float16_t(float(bitfieldExtract(int(word), int(t * 8u), 8)) * d);
                }
            }
        }
        barrier();

